const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closingDate=String(input.closing_date??"").trim();
const sellerReady=Boolean(input.seller_id||input.seller_name);
const buyerReady=Boolean(input.buyer_id||input.buyer_name);
const titleReady=Boolean(input.title_company||input.title_contact||input.title_status);
const attorneyReady=Boolean(input.attorney||input.attorney_contact||input.attorney_status);
const fundingReady=Boolean(input.funding_source||input.funding_contact||input.funding_status);
const brokerReady=Boolean(input.broker||input.broker_contact||input.broker_status);
const identityReady=Boolean(dealId&&leadId&&propertyId);
const coordinationReady=identityReady&&Boolean(closingDate)&&sellerReady&&buyerReady&&!blockers.length;
const missing=[];
if(!dealId)missing.push("deal_id");if(!leadId)missing.push("lead_id");if(!propertyId)missing.push("property_id");
if(!closingDate)missing.push("closing_date");if(!sellerReady)missing.push("seller");if(!buyerReady)missing.push("buyer");
if(!titleReady)missing.push("title");if(!attorneyReady)missing.push("attorney");if(!fundingReady)missing.push("funding");if(!brokerReady)missing.push("broker");
let status=coordinationReady?"coordination_ready":"coordination_incomplete";
let nextWorkflow=coordinationReady?"WF-305":"WF-126";
let reason=coordinationReady?"transaction is ready for closing-party coordination":"closing coordination prerequisites are incomplete";
return [{json:{...input,workflow:"WF-304",workflow_name:"Transaction Readiness → Title/Attorney/Funding/Broker Closing Coordination Controller",status,closing_coordination:{identity_ready:identityReady,closing_date:closingDate||null,seller_ready:sellerReady,buyer_ready:buyerReady,parties:{title_ready:titleReady,attorney_ready:attorneyReady,funding_ready:fundingReady,broker_ready:brokerReady},missing,blockers},next_workflow:nextWorkflow,human_review_required:true,audit:{event_type:"closing_coordination_readiness",idempotency_key:input.idempotency_key||`wf-304:${dealId||"unknown"}:${input.version||1}`,reason}}}];
